import React from 'react';

import PageHeader from '@components/PageHeader';
import PohBreadcrumbs from '@ui-kit/Breadcrumb';
import PohContainer from '@ui-kit/layout/Container';

import FriendsList from '../components/FriendsList';

interface IUsersPageProps {}

const UsersPage: React.FC<IUsersPageProps> = () => {
  return (
    <section>
      <PohBreadcrumbs data={[{ href: '/users', text: 'Походники', active: true }]} />
      <PohContainer>
        <PageHeader title="Походники"></PageHeader>
        <p>
          Друзей-походников нельзя добавить или удалить. В друзья попадают те замечательные люди, с
          которыми вы вместе были в походах.
        </p>
        <FriendsList />
      </PohContainer>
    </section>
  );
};

export default UsersPage;
